# Reconstruct and output the full flat list
points = [
    (1, 0, 0), (1, 0, 1), (1, 0, 2), (1, 1, 0), (1, 1, 1), (1, 1, 2),
    (1, 2, 0), (1, 2, 1), (1, 2, 2), (0, 1, 0), (0, 1, 1), (0, 1, 2), (0, 0, 1),
]

line_coeffs = [
    (1, 0, 0), (1, 0, 1), (1, 0, 2), (1, 1, 0), (1, 1, 1), (1, 1, 2),
    (1, 2, 0), (1, 2, 1), (1, 2, 2), (0, 1, 0), (0, 1, 1), (0, 1, 2), (0, 0, 1),
]

lines = []
for (a, b, c) in line_coeffs:
    line_points = []
    for i, (x, y, z) in enumerate(points):
        if (a*x + b*y + c*z) % 3 == 0:
            line_points.append(i)
    lines.append(line_points)

blocks = []
for line in lines:
    for _ in range(3):
        blocks.append(line)

v = 13
b = 39
matrix = [[0]*b for _ in range(v)]

for j, block in enumerate(blocks):
    for i in block:
        matrix[i][j] = 1

flat = []
for i in range(v):
    for j in range(b):
        flat.append(matrix[i][j])

print(flat)
